require('dotenv').config();const prisma=require('../src/utils/prisma');const apply=process.argv.includes('--apply');
async function run(){const links=await prisma.productSupplier.findMany({where:{price:{gt:0},product:{organizationProductId:{not:null}},supplier:{organizationSupplierId:{not:null}}},include:{product:{select:{organizationProductId:true,purchaseUnit:true,unit:true,packQuantity:true,establishmentId:true}},supplier:{select:{organizationSupplierId:true,establishmentId:true}}}});const groups=new Map();for(const link of links){if(link.product.establishmentId!==link.supplier.establishmentId)continue;const key=`${link.supplier.organizationSupplierId}:${link.product.organizationProductId}`;groups.set(key,[...(groups.get(key)||[]),link]);}const existing=await prisma.supplierCatalogItem.findMany({select:{organizationSupplierId:true,organizationProductId:true}});const existingKeys=new Set(existing.map(x=>`${x.organizationSupplierId}:${x.organizationProductId}`));const safe=[],conflicts=[];for(const[key,items]of groups){if(existingKeys.has(key))continue;const signatures=new Set(items.map(x=>`${Number(x.price).toFixed(4)}|${x.product.purchaseUnit||x.product.unit}|${Number(x.product.packQuantity||1).toFixed(3)}`));const[organizationSupplierId,organizationProductId]=key.split(':');const first=items[0];const entry={organizationSupplierId,organizationProductId,commercialUnit:first.product.purchaseUnit||first.product.unit,unitsPerPackage:Number(first.product.packQuantity||1),packagePrice:Number(first.price),localLinks:items.length};if(signatures.size===1)safe.push(entry);else conflicts.push({...entry,signatures:[...signatures]});}if(apply){for(const item of safe){await prisma.supplierCatalogItem.create({data:{organizationSupplierId:item.organizationSupplierId,organizationProductId:item.organizationProductId,commercialUnit:item.commercialUnit,unitsPerPackage:item.unitsPerPackage,packagePrice:item.packagePrice,normalizedUnitPrice:Number((item.packagePrice/item.unitsPerPackage).toFixed(4)),available:true,status:'ACTIVE'}});}}console.log(JSON.stringify({mode:apply?'apply':'preview',safe: safe.length,conflicts:conflicts.length,created:apply?safe.length:0,safeItems:safe,conflictItems:conflicts},null,2));}
run().catch(e=>{console.error(e.message);process.exitCode=1;}).finally(()=>prisma.$disconnect());
